static bool decode_request(const std::string & line, const CliConfig & shared, CliConfig & cfg) {
    if (line.empty() || line.size() > 1024 * 1024) return false;
    std::vector<std::string> args{"request"};
    std::istringstream input(line);
    std::string hex;
    auto digit = [](char c) -> int {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        return -1;
    };
    while (std::getline(input, hex, '\t')) {
        if (hex.size() % 2) return false;
        std::string decoded;
        for (size_t i = 0; i < hex.size(); i += 2) {
            int a = digit(hex[i]), b = digit(hex[i+1]);
            if (a < 0 || b < 0 || (a == 0 && b == 0)) return false;
            decoded.push_back(char(a * 16 + b));
        }
        args.push_back(decoded);
    }
    const std::set<std::string> allowed{"-t", "-o", "-r", "--prompt-wav", "--prompt-text",
        "--seed", "--steps", "--timesteps", "--cfg", "--temperature"};
    std::set<std::string> seen;
    if ((args.size() - 1) % 2) return false;
    for (size_t i = 1; i < args.size(); i += 2) {
        if (!allowed.count(args[i]) || !seen.insert(args[i]).second) return false;
        if (args[i+1].empty()) return false;
        if (args[i] == "--seed" || args[i] == "--steps" || args[i] == "--timesteps") {
            char * end = nullptr;
            const long n = std::strtol(args[i+1].c_str(), &end, 10);
            if (!end || *end || n < 0 || n > std::numeric_limits<int>::max() ||
                (args[i] != "--seed" && n == 0)) return false;
        } else if (args[i] == "--cfg" || args[i] == "--temperature") {
            char * end = nullptr;
            const float v = std::strtof(args[i+1].c_str(), &end);
            if (!end || *end || !std::isfinite(v) || v < 0) return false;
        }
    }
    for (const char * flag : {"-t", "-o", "--seed", "--steps", "--timesteps", "--cfg", "--temperature"})
        if (!seen.count(flag)) return false;
    args.push_back(shared.base_lm_path); args.push_back(shared.acoustic_path);
    std::vector<char *> argv;
    for (auto & arg : args) argv.push_back(&arg[0]);
    cfg = CliConfig{};
    if (!parse_args(int(argv.size()), argv.data(), cfg)) return false;
    cfg.use_gpu = shared.use_gpu;
    cfg.n_gpu_layers = shared.n_gpu_layers;
    return true;
}

template<class Runtime>
static bool initialize(Runtime & runtime, const CliConfig & cfg) {
    const auto start = std::chrono::steady_clock::now();
    if (!runtime.init(cfg.base_lm_path, cfg.acoustic_path, cfg.n_gpu_layers, cfg.use_gpu)) {
        LOG_ERR("Failed to initialize VoxCPM2 runtime: %s\n", runtime.last_error().c_str());
        return false;
    }
    runtime.set_feature_cache_limit(size_t(cfg.feature_cache_mb) * 1024 * 1024);
    LOG_INF("MI1_TIMING initialization_seconds=%.6f\n",
        std::chrono::duration<double>(std::chrono::steady_clock::now() - start).count());
    return true;
}

template<class Runtime>
static int run_requests(const CliConfig & shared, std::istream & input, std::ostream & reply) {
    Runtime runtime;
    bool loaded = false;
    size_t index = 0;
    std::string line;
    // Bound each input line while reading, rather than allocating arbitrarily large lines.
    while (input.peek() != std::char_traits<char>::eof()) {
        line.clear();
        char ch;
        while (input.get(ch) && ch != '\n') {
            if (line.size() >= 1024 * 1024) return 1;
            line.push_back(ch);
        }
        ++index;
        CliConfig cfg;
        int rc = 1;
        if (decode_request(line, shared, cfg)) {
            if (!loaded) { loaded = initialize(runtime, shared); }
            if (loaded) rc = run_request(runtime, cfg);
        }
        common_log_flush(common_log_main());
        std::fflush(stderr);
        reply << "MI1_REQUEST\t" << index << '\t' << rc << '\n' << std::flush;
        if (rc) return rc; // fail-stop; no later request can conceal a failed one
    }
    return 0;
}

static int run_synthesis(const CliConfig & cfg) {
    VoxCPM2Runtime runtime;
    if (!initialize(runtime, cfg)) return 1;
    return run_request(runtime, cfg);

