bool VoxCPM2Runtime::build_combined_prefill_inputs(const std::vector<int32_t> & text_token_ids,
                                                   const std::vector<float> & reference_feat,
                                                   const std::vector<float> & prompt_feat,
                                                   bool append_audio_start,
                                                   VoxCPM2PrefillInputs & inputs) {
    // OpenBMB VoxCPM2: [ref_start, ref audio, ref_end, joined text,
    // audio_start, prompt audio]. The two audio regions have complementary masks.
    if (!build_reference_prefill_inputs(text_token_ids, reference_feat, append_audio_start, inputs)) {
        return false;
    }
    const size_t stride = static_cast<size_t>(feat_dim()) * static_cast<size_t>(patch_size());
    if (prompt_feat.empty() || prompt_feat.size() % stride != 0) {
        inputs = {};
        return fail("prompt features must contain whole VoxCPM2 latent patches");
    }
    const size_t frames = prompt_feat.size() / stride;
    inputs.token_ids.insert(inputs.token_ids.end(), frames, 0);
    inputs.text_mask.insert(inputs.text_mask.end(), frames, 0);
    inputs.feat_mask.insert(inputs.feat_mask.end(), frames, 1);
    inputs.audio_feat.insert(inputs.audio_feat.end(), prompt_feat.begin(), prompt_feat.end());
    return true;
}

bool VoxCPM2Runtime::validate_combined_context(size_t prefill_length, int max_steps, size_t capacity) {
    if (max_steps <= 0) {
        return fail("combined mode requires positive max_steps");
    }
    if (prefill_length > capacity || static_cast<size_t>(max_steps) > capacity - prefill_length) {
        return fail("combined reference, text, prompt and max_steps exceed the model context capacity");
    }
    return true;
}

void VoxCPM2Runtime::seed_combined_decode_context(const VoxCPM2PrefillInputs & inputs) {
    const size_t stride = static_cast<size_t>(feat_dim()) * static_cast<size_t>(patch_size());
    // Only the trailing prompt is contiguous with generated speech. For very
    // short prompts, stop at the text boundary instead of entering ref audio.
    for (size_t i = inputs.feat_mask.size(); i-- > 0 && output_pool.size() < 3;) {
        if (!inputs.feat_mask[i]) {
            break;
        }
        output_pool.insert(output_pool.begin(), std::vector<float>(
            inputs.audio_feat.begin() + i * stride, inputs.audio_feat.begin() + (i + 1) * stride));
    }
}

bool VoxCPM2Runtime::prepare_combined(const std::string & target_text, const std::string & prompt_text,
                                      const std::vector<float> & reference_wav, int reference_sr,
                                      const std::vector<float> & prompt_wav, int prompt_sr,
                                      const VoxCPM2GenerateParams & params, VoxCPM2PrefillInputs & inputs) {
    clear_error();
    if (target_text.empty() || prompt_text.empty() || reference_wav.empty() || prompt_wav.empty()) {
        return fail("combined mode requires target text, prompt transcript and both WAV inputs");
    }
    if (reference_sr <= 0 || prompt_sr <= 0) {
        return fail("combined mode requires positive sample rates for both WAV inputs");
    }
    // Tokenize once: tokenization at the join must match Python.
    const auto tokens = tokenize_text(prompt_text + target_text, false, true);
    if (tokens.empty()) {
        return false;
    }
    const auto reference_feat = encode_reference_audio(reference_wav, reference_sr);
    if (reference_feat.empty()) {
        return false;
    }
    const auto prompt_feat = encode_reference_audio(prompt_wav, prompt_sr, true);
    if (prompt_feat.empty()) {
        return false;
    }
    const size_t stride = static_cast<size_t>(feat_dim()) * static_cast<size_t>(patch_size());
    const size_t audio_start = params.append_audio_start && tokens.back() != kAudioStartToken ? 1 : 0;
    const size_t prefill_length = 2 + reference_feat.size() / stride + tokens.size() + audio_start +
                                  prompt_feat.size() / stride;
    const size_t capacity = std::min(static_cast<size_t>(llama_n_ctx(base_lm.ctx)),
                                     static_cast<size_t>(residual_lm.kv_cache.max_length));
    if (!validate_combined_context(prefill_length, params.max_steps, capacity) ||
        !build_combined_prefill_inputs(tokens, reference_feat, prompt_feat, params.append_audio_start, inputs)) {
        return false;
    }
    if (params.seed != 0) {
        rng.seed(params.seed);
    }
    return prefill(inputs);
}

std::vector<float> VoxCPM2Runtime::generate_with_combined(const std::string & target_text,
                                                         const std::string & prompt_text,
                                                         const std::vector<float> & reference_wav, int reference_sr,
                                                         const std::vector<float> & prompt_wav, int prompt_sr,
                                                         const VoxCPM2GenerateParams & params) {
    VoxCPM2PrefillInputs inputs;
    if (!prepare_combined(target_text, prompt_text, reference_wav, reference_sr, prompt_wav, prompt_sr,
                          params, inputs)) {
        return {};
    }
    // Warm the causal VAE with up to three trailing prompt patches, then trim
    // their waveform. These patches do not count as generated decode steps.
    seed_combined_decode_context(inputs);
    const size_t context_patches = output_pool.size();
    decode_loop(params, nullptr);
    if (!last_error_msg.empty()) {
        return {};
    }
    if (output_pool.size() == context_patches) {
        fail("combined generation produced no audio patches");
        return {};
    }
    auto wav = decode_to_waveform(params.target_sr);
    if (wav.empty()) {
        return {};
    }
    const size_t trim = context_patches * static_cast<size_t>(patch_size()) *
                        static_cast<size_t>(audio_vae.config.decode_hop_length());
    if (wav.size() <= trim) {
        fail("combined waveform is shorter than its prompt context");
        return {};
    }
    wav.erase(wav.begin(), wav.begin() + trim);
    return wav;
}

bool VoxCPM2Runtime::generate_with_combined_streaming(const std::string & target_text,
                                                     const std::string & prompt_text,
                                                     const std::vector<float> & reference_wav, int reference_sr,
                                                     const std::vector<float> & prompt_wav, int prompt_sr,
                                                     const VoxCPM2AudioChunkCallback & callback,
                                                     const VoxCPM2GenerateParams & params) {
    VoxCPM2PrefillInputs inputs;
    if (!prepare_combined(target_text, prompt_text, reference_wav, reference_sr, prompt_wav, prompt_sr,
                          params, inputs)) {
        return false;
    }
    // Python streaming sends only newly predicted patches to the stateful VAE.
    return decode_streaming_from_ready_state(params, callback);

