#include <cstring>
#include <list>
#include <string>
#include <vector>

// Exact PCM-bit identity, no hash collisions. Each cache belongs to one loaded
// runtime (immutable models/backend/encoder). Never stores KV or text context.
class MI1FeatureCache {
    struct Entry { std::string key; std::vector<float> features; };
    std::list<Entry> entries;
    size_t used = 0, limit = 0;
    static size_t cost(const std::string & key, size_t floats) {
        return key.capacity() + 1 + floats * sizeof(float) + sizeof(Entry) + 2 * sizeof(void *);
    }
public:
    void clear() { entries.clear(); used = 0; }
    void set_limit(size_t bytes) { clear(); limit = bytes; }
    size_t bytes() const { return used; }
    static std::string key(const std::vector<float> & pcm, int rate, bool pad_left,
                           int encoder_rate, int hop, int dim, int patch) {
        std::string result = "mi1-encoder-features/1:mono-float32:";
        for (int v : {rate, int(pad_left), encoder_rate, hop, dim, patch}) {
            result += std::to_string(v) + ":";
        }
        result.append(reinterpret_cast<const char *>(pcm.data()), pcm.size() * sizeof(float));
        return result;
    }
    bool get(const std::string & key, std::vector<float> & result) {
        for (auto it = entries.begin(); it != entries.end(); ++it) {
            if (it->key == key) {
                result = it->features;
                entries.splice(entries.begin(), entries, it);
                return true;
            }
        }
        return false;
    }
    void put(std::string key, const std::vector<float> & result) {
        if (result.empty()) return;
        const size_t entry_cost = cost(key, result.size());
        if (entry_cost > limit) return;
        for (auto it = entries.begin(); it != entries.end(); ++it) {
            if (it->key == key) {
                used -= cost(it->key, it->features.size());
                entries.erase(it);
                break;
            }
        }
        while (used + entry_cost > limit && !entries.empty()) {
            used -= cost(entries.back().key, entries.back().features.size());
            entries.pop_back();
        }
        entries.push_front({std::move(key), result});
        used += entry_cost;
    }
    bool enabled() const { return limit > 0; }
};
